/**
 * Pip, the Speechworks mascot, drawn live: idle life (blink, glance, breath, hair), 8 faces and the kit's 5 hand moves.
 *
 * - Ported from the sw-characters phone prototype (native/prototype/App.tsx). Only the drawing is here: every number comes from
 *   the kit core (./core, GENERATED by sw-characters core/scripts/export-app.mjs). Do not edit ./core or ./pip-app.json.
 * - The website framing: Pip stands on his colour blob. The figure and the hands are cut by ONE outline (everything above the
 *   blob's cut line, then the blob's lower curve), so the body always ends on the blob's curve and the full collar shows.
 * - UI thread: a Reanimated frame callback solves the frame; the SVG parts read it through animated props. No React render per frame.
 * - Pip is a reserved look: app users cannot build him in any avatar editor (sw-characters kit/catalog-pip.json).
 * - Reduced motion: Pip stands still (no idle, no hand moves); a face change still happens.
 */
import React, { forwardRef, memo, useCallback, useEffect, useImperativeHandle, useMemo, useRef, useState } from "react";
import { View } from "react-native";
import Svg, { Circle, ClipPath, Defs, Ellipse, G, LinearGradient, Path, RadialGradient, Stop, parse } from "react-native-svg";
import Animated, { Easing, runOnJS, runOnUI, useAnimatedProps, useAnimatedStyle, useFrameCallback, useReducedMotion, useSharedValue, withSequence, withSpring, withTiming } from "react-native-reanimated";
import { FACE_MS, HAND_ART, faceGo, faceNow, faceStill, hairElement, hairPath, overlayIdle, prepare, prepareIdle, solveFrame, solveIdle } from "./core/app.js";
import PIP_APP from "./pip-app.json";

export type PipVariant = "pip" | "pip-f";
export type PipMove = "h-palms" | "h-wave" | "h-cheek" | "h-chin" | "h-heart";
export type PipFace = "calm" | "smile" | "laugh" | "proud" | "curious" | "listening" | "thinking" | "warm";
export const PIP_MOVES: PipMove[] = ["h-palms", "h-wave", "h-cheek", "h-chin", "h-heart"];
export type PipBody = "hop" | "pop" | "sway";
export const PIP_BODY: PipBody[] = ["hop", "pop", "sway"];
export const PIP_FACES: PipFace[] = ["calm", "smile", "laugh", "proud", "curious", "listening", "thinking", "warm"];

export interface PipHandle {
  /** Play one hand move (3.3 to 4 s). Every move starts and ends on the calm face: if Pip shows another face, it eases to calm
   *  first (340 ms), then the move starts. Resolves when the move ends; set a face after that. Under reduced motion it resolves at once. */
  play: (move: PipMove) => Promise<void>;
  /** Change the face (340 ms morph from the face as it is now). */
  face: (name: PipFace) => void;
  /** A whole-body motion (no hands): hop (a small jump, 0.5 s), pop (a quick grow, 0.5 s) or sway (a side to side tilt, 0.7 s).
   *  The whole picture moves, blob too, pivoting at Pip's feet. Can run with a face change or a hand move. Under reduced motion it resolves at once. */
  body: (kind: PipBody) => Promise<void>;
}
export interface PipProps {
  variant?: PipVariant;
  /** Width in px. The height follows the picture (372 x 322). */
  size: number;
  /** false: no colour blob behind Pip (the body is still cut by the blob's curve). */
  blob?: boolean;
  /** The blob colour; default: Pip's own blob colour. */
  blobColour?: string;
  face?: PipFace;
  /** The colour right behind Pip (the screen or card he stands on). Below the blob's cut line, Pip is covered with it, so his
   *  body ends exactly on the blob's curve. Pip needs a plain colour behind him. */
  backdrop: string;
  /** Pictures and checks only: hold this move at this many ms (no idle motion). */
  hold?: [PipMove, number] | null;
  /** Pip lab only (speed checks): draw without the blob cut. */
  labNoCut?: boolean;
  /** Pip lab only (speed checks): draw without the hand layer. */
  labNoHands?: boolean;
}

// the hair path is rewritten at most every Nth frame (the springs are slow; the head still moves every frame). Pip-f's bob has
// 9 moving pieces, so it repaints every 3rd frame (founder, 2026-11-25, S2 A)
const HAIR_EVERY: Record<PipVariant, number> = { pip: 2, "pip-f": 3 };
const BLUSH_K = 0.8;           // founder: blush a little lighter than the studio
const IDLE_SEC = 40;           // the idle (blink, glance, breath, hair) is solved once for 40 s, then loops
const VIEW = { x: -24, y: -6, w: 372, h: 322 };   // the site picture is 320 x 310; the blob reaches a little outside it
const SLOTS = ["palmL", "palmR", "wave", "cheek", "chin", "heart3"];
const SHADOW_SLOTS = ["palmL", "palmR", "wave"];
const ID6 = [1, 0, 0, 1, 0, 0], AWAY = [1, 0, 0, 1, 0, 3000], NONE = "M0 0";
const ART: any = HAND_ART;

const kids = (xml: string) => (xml ? (parse("<svg>" + xml + "</svg>") as any)?.children : null);
const camel = (a: Record<string, string>) => { const o: any = {}; for (const k in a) o[k.replace(/-(\w)/g, (_, c) => c.toUpperCase())] = a[k]; return o; };

/** One Pip, ready to draw: the look (baked), its moments and idle (prepared once per variant), the static SVG nodes. */
type Bundle = { L: any; look: any; I: any; FK: any; PREP: Record<string, any>; ST: any; COL: any };
const CACHE: Partial<Record<PipVariant, Bundle>> = {};
function bundle(v: PipVariant): Bundle {
  const hit = CACHE[v]; if (hit) return hit;
  const L: any = PIP_APP.looks.find((x: any) => x.id === v) ?? PIP_APP.looks[0], look = L.look;
  const I = prepareIdle(look, { seconds: IDLE_SEC }), PREP: Record<string, any> = {};
  for (const id of PIP_MOVES) PREP[id] = prepare(id, look);
  const FR = look.face.el;
  const ST = { nose: kids(FR.nose), tongue: kids(FR.tongue), cheek: kids(FR.cheek), layers: look.layers.map((l: any) => (l.hairItems ? null : kids(l.svg))),
    eyes: { ring: look.eyes.ring.map(kids), white: look.eyes.white.map(kids), pupil: look.eyes.pupil.map(kids) },
    shadow: look.shadow ? look.shadow.regions.map((r: any) => kids(r.svg)) : [] };
  const b = { L, look, I, FK: I.fk, PREP, ST, COL: PREP["h-palms"].colours };
  CACHE[v] = b; return b;
}

const AG = Animated.createAnimatedComponent(G), AP = Animated.createAnimatedComponent(Path), ALG = Animated.createAnimatedComponent(LinearGradient);
type Sel = (f: any) => any;
function pick(f: any, art: string) { "worklet"; for (let k = 0; k < f.hands.length; k++) if (f.hands[k].art === art && f.hands[k].show) return f.hands[k]; return null; }
/** A group that moves: sel gives { matrix, opacity }. */
function DG({ fs, sel, children, ...rest }: any) { const ap = useAnimatedProps(() => { const o = sel(fs.value); return { matrix: o.matrix, opacity: o.opacity }; }); return <AG {...rest} animatedProps={ap}>{children}</AG>; }
/** A path that changes shape: sel gives { d, ... }. */
function DP({ fs, sel, ...rest }: any) { const ap = useAnimatedProps(() => sel(fs.value)); return <AP {...rest} animatedProps={ap} />; }
/** A gradient whose ends move: sel gives { x1, y1, x2, y2 }. */
function DLG({ fs, sel, children, ...rest }: any) { const ap = useAnimatedProps(() => sel(fs.value)); return <ALG {...rest} animatedProps={ap}>{children}</ALG>; }
/** A hair path: rebuilt on the UI thread from the hair state (written only when the hair moved). */
function HP({ hs, plan, k, d0, attrs }: any) { const ap = useAnimatedProps(() => { const h = hs.value; return h ? { d: hairPath(plan, k, h) || d0 } : { d: d0 }; }); return <AP {...attrs} d={d0} animatedProps={ap} />; }
/** A hair circle / ellipse that moves. */
function HE({ hs, plan, k, tag, attrs }: any) {
  const ap = useAnimatedProps(() => { const h = hs.value, o = h ? hairElement(plan, k, h) : null; return { matrix: o ? [1, 0, 0, 1, o[0], o[1]] : ID6 }; });
  const El: any = tag === "circle" ? Circle : Ellipse; return <AG animatedProps={ap as any}><El {...attrs} /></AG>;
}

let UID = 0;
const ABS = { position: "absolute" as const, left: 0, top: 0 };
type Motion = "body" | "collar" | "lift" | "head" | "hair" | "face";
const motionOf = (l: any): Motion => (l.cls === "face" ? "face" : l.hairItems ? "hair" : l.cls === "rig" ? "head" : l.cls === "body" ? "body" : l.cls === "collar" ? "collar" : "lift");
/** The kit frame inside the picture: picture = k * kit + o (the stage transform after the kit zoom). */
const kitToPicture = (L: any) => { const S = L.stage, z = L.look.zoom, bp = L.look.bottomPad; return { k: S.scale * z, ox: S.scale * 500 * (1 - z) + S.tx, oy: S.scale * (1000 + bp - 1000 * z) + S.ty }; };

/**
 * One layer of Pip: its own picture, absolutely stacked, moved by a NATIVE transform (the graphics chip moves it; nothing is
 * painted again). A layer whose shapes never change (body, collar, head, glasses, blob) is painted once. Only hair, face and
 * hands change shape, so only those repaint.
 */
function Layer({ fs, motion, K, u, w, h, children }: { fs: any; motion: Motion | "still"; K: { k: number; ox: number; oy: number }; u: number; w: number; h: number; children: React.ReactNode }) {
  const st = useAnimatedStyle(() => {
    const f = fs.value;
    if (motion === "head" || motion === "hair" || motion === "face") {
      // the head matrix acts in kit units; in the picture it is K H K^-1; on screen (dp, origin top left) the translation is u * (A vb + T - vb)
      const H = f.headMatrix, a = H[0], b = H[1], c = H[2], d = H[3];
      const Tx = K.ox - (a * K.ox + c * K.oy) + K.k * H[4], Ty = K.oy - (b * K.ox + d * K.oy) + K.k * H[5];
      return { transform: [{ translateX: u * (a * VIEW.x + c * VIEW.y + Tx - VIEW.x) }, { translateY: u * (b * VIEW.x + d * VIEW.y + Ty - VIEW.y) }, { rotate: Math.atan2(b, a) + "rad" }, { scale: Math.hypot(a, b) }] };
    }
    const dy = motion === "body" ? f.breathBody - f.shoulderLift : motion === "collar" ? f.breathCollar - f.shoulderLift : motion === "lift" ? -f.shoulderLift : 0;
    return { transform: [{ translateY: u * K.k * dy }] };
  });
  return (
    <Animated.View pointerEvents="none" style={[ABS, { width: w, height: h, transformOrigin: "left top" }, st]}>
      <Svg width={w} height={h} viewBox={`${VIEW.x} ${VIEW.y} ${VIEW.w} ${VIEW.h}`}>{children}</Svg>
    </Animated.View>);
}

const Figure = memo(function Figure({ fs, hs, B, uid, w, h, blob, blobColour, backdrop, noCut, noHands, arts }: { fs: any; hs: any; B: Bundle; uid: string; w: number; h: number; blob: boolean; blobColour?: string; backdrop: string; noCut?: boolean; noHands?: boolean; arts: string[] }) {
  const p = { fs }, L = B.L, LOOK = B.look, ST = B.ST, plan = B.I.hair, eg = LOOK.eyes.eg, SHW = LOOK.shadow, FR = LOOK.face.el, COL = B.COL, S = L.stage;
  const K = kitToPicture(L), u = w / VIEW.w;
  const id = (s: string) => uid + s, url = (s: string) => `url(#${uid}${s})`;
  // only the hand drawings of the move being played are mounted (each one is about ten animated parts); idle mounts none
  const AS = SLOTS.map((art, i) => [art, i] as const).filter(([a]) => arts.includes(a));
  const STAGE_T = `translate(${S.tx} ${S.ty}) scale(${S.scale})`;
  const ZOOM_T = `translate(500 ${1000 + LOOK.bottomPad}) scale(${LOOK.zoom}) translate(-500 -1000)`;
  const kit = (nodes: React.ReactNode) => <G transform={STAGE_T}><G transform={ZOOM_T}>{nodes}</G></G>;
  const stops = (s: number[][]) => s.map((q, i) => <Stop key={i} offset={q[0]} stopColor={COL.seam} stopOpacity={q[1]} />);
  const lift: Sel = f => { "worklet"; return { matrix: [1, 0, 0, 1, 0, -f.shoulderLift], opacity: 1 }; };
  const brow: Sel = f => { "worklet"; return { matrix: [1, 0, 0, 1, 0, f.browDip - f.browLift], opacity: 1 }; };
  const eyesOn: Sel = f => { "worklet"; return { matrix: ID6, opacity: f.eyes.on ? 1 : 0 }; };
  const pupil: Sel = f => { "worklet"; return { matrix: [1, 0, 0, 1, f.eyes.pupilX, f.eyes.pupilY], opacity: 1 }; };
  const cheekS: Sel = f => { "worklet"; return { matrix: f.faceR.cheekM, opacity: f.faceR.cheekO }; };
  const teethS: Sel = f => { "worklet"; return { matrix: f.faceR.teethM, opacity: f.faceR.teethO }; };
  const tongueS: Sel = f => { "worklet"; return { matrix: f.faceR.tongueM, opacity: f.faceR.tongueO }; };
  const iCollar = LOOK.layers.findIndex((l: any) => l.cls === "collar");

  // the face layer: blush (cut to the skull), eyes, lids, cheek lift, lash line, brow, nose, mouth, teeth, tongue. The head moves the whole layer.
  const face = <>
    <Defs>
      <ClipPath id={id("hc")}>{ST.layers[iCollar - 1]}</ClipPath>
      {[0, 1].map(i => <ClipPath key={i} id={id("ec" + i)}><Ellipse cx={eg[i].cx} cy={eg[i].wcy} rx={eg[i].wrx} ry={eg[i].wry} /></ClipPath>)}
      {/* blush: a soft-edged ellipse (radial gradient), not a blur filter every frame */}
      <RadialGradient id={id("bl")} cx="50%" cy="50%" r="50%">{[[0, 1], [0.24, 0.97], [0.4, 0.8], [0.54, 0.5], [0.7, 0.22], [0.85, 0.06], [1, 0]].map(([o, a], i) => <Stop key={i} offset={o} stopColor={FR.blush[0].fill} stopOpacity={a} />)}</RadialGradient>
      <ClipPath id={id("ck")}>{eg.map((g: any, j: number) => { const top = g.cy - g.ry, bot = g.wcy + g.wry; return <Ellipse key={j} cx={g.cx} cy={(top + bot) / 2} rx={Math.max(g.rx, g.wrx) + 3} ry={(bot - top) / 2 + 3} />; })}</ClipPath>
    </Defs>
    {kit(<>
      <G clipPath={url("hc")}>{FR.blush.map((q: any, j: number) => (
        <DG key={"bl" + j} {...p} sel={(f: any) => { "worklet"; return { matrix: f.faceR.blushM[j], opacity: f.faceR.blushO * BLUSH_K }; }}>
          <Ellipse cx={q.cx} cy={q.cy} rx={q.rx + 30} ry={q.ry + 30} fill={url("bl")} /></DG>))}</G>
      <DG {...p} sel={eyesOn}><G>{[0, 1].map(e => (
        <G key={e}>{ST.eyes.ring[e]}{ST.eyes.white[e]}<G clipPath={url("ec" + e)}><DG {...p} sel={pupil}>{ST.eyes.pupil[e]}</DG></G></G>))}</G></DG>
      {/* the lids: skin-coloured shapes over the open eye (no moving clip: Android does not redraw one) */}
      <DP {...p} fill={LOOK.skin} sel={(f: any) => { "worklet"; return { d: f.eyes.lidD || NONE }; }} />
      {FR.cheek ? <G clipPath={url("ck")}><DG {...p} sel={cheekS}>{ST.cheek}</DG></G> : null}
      <DP {...p} fill="none" stroke={LOOK.eyes.lashColour} strokeLinecap="round" strokeLinejoin="round" strokeWidth={3} sel={(f: any) => { "worklet"; return { d: f.eyes.lashOn ? f.eyes.lashD : NONE, strokeWidth: f.eyes.lashSw }; }} />
      <DG {...p} sel={brow}><DP {...p} fill="none" stroke={FR.brow.stroke} strokeWidth={FR.brow.sw} strokeLinecap="round" strokeLinejoin="round" sel={(f: any) => { "worklet"; return { d: f.faceR.browD }; }} /></DG>
      {ST.nose}
      <DP {...p} fill={FR.mouthCol} stroke={FR.mouthCol} strokeLinecap="round" strokeLinejoin="round" sel={(f: any) => { "worklet"; return { d: f.faceR.mouthD, strokeWidth: f.faceR.mouthSw }; }} />
      {FR.teethFill ? <DG {...p} sel={teethS}><DP {...p} fill={FR.teethFill} sel={(f: any) => { "worklet"; return { d: f.faceR.teethD }; }} /></DG> : null}
      {FR.tongue ? <DG {...p} sel={tongueS}>{ST.tongue}</DG> : null}
    </>)}
  </>;
  const hair = (l: any, i: number) => <>
    {l.clip ? <Defs><ClipPath id={id("ov" + i)}><Path d={l.clip} /></ClipPath></Defs> : null}
    {kit(<G clipPath={l.clip ? url("ov" + i) : undefined}>{l.hairItems.map((it: any) => {
      const mv = plan && plan.items[it.k] && (plan.items[it.k].mov || (plan.items[it.k].el && plan.items[it.k].w));
      if (it.tag === "path") return mv ? <HP key={it.k} hs={hs} plan={plan} k={it.k} d0={it.d} attrs={camel(it.attrs)} /> : <Path key={it.k} d={it.d} {...camel(it.attrs)} />;
      const El: any = it.tag === "circle" ? Circle : Ellipse;
      return mv ? <HE key={it.k} hs={hs} plan={plan} k={it.k} tag={it.tag} attrs={camel(it.attrs)} /> : <El key={it.k} {...camel(it.attrs)} />; })}</G>)}
  </>;
  // the look's layers, in order; neighbours that move the same way share one picture
  const groups: { motion: Motion; idx: number[] }[] = [];
  LOOK.layers.forEach((l: any, i: number) => { const m = motionOf(l), last = groups[groups.length - 1];
    if (last && last.motion === m && m !== "face" && m !== "hair") last.idx.push(i); else groups.push({ motion: m, idx: [i] }); });
  const layers = groups.map((g, n) => (
    <Layer key={n} fs={fs} motion={g.motion} K={K} u={u} w={w} h={h}>
      {g.motion === "face" ? face : g.motion === "hair" ? hair(LOOK.layers[g.idx[0]], g.idx[0]) : kit(g.idx.map(i => <G key={i}>{ST.layers[i]}</G>))}
    </Layer>));

  // the hands (mounted only while a move plays): sleeves, cuffs, seams, the contact shadow on the shirt and the arm shadow
  // Pip's baked look has armShadow false (invisible on his near-black jacket, 40% of a Palms / Wave frame): then none is drawn
  const armShadow = LOOK.armShadow !== false && SHW && SHW.regions.length && SHADOW_SLOTS.some(a => arts.includes(a)) ? <G>{SHW.regions.map((r: any, k: number) => (
    <DG key={k} {...p} sel={(f: any) => { "worklet"; const m = f.shadowM; return { matrix: m ? m[k].slice(0, 6) : ID6, opacity: m ? 1 : 0 }; }}>
      <G clipPath={url("shc" + k)}>
        <DG {...p} sel={(f: any) => { "worklet"; const m = f.shadowM; return { matrix: m ? m[k].slice(6) : ID6, opacity: 1 }; }}>
          {SHADOW_SLOTS.filter(a => arts.includes(a)).map(art => (
            <DG key={art} {...p} sel={(f: any) => { "worklet"; const h = pick(f, art); return { matrix: h && h.armShadow.on ? h.armShadow.matrix : AWAY, opacity: h && h.armShadow.on ? SHW.opacity : 0 }; }}>
              {ART[art].paths.map((q: any, j: number) => <Path key={j} d={q.d} fill={q.fill ? r.col : "none"} fillRule={q.evenOdd ? "evenodd" : "nonzero"} stroke={q.stroke ? r.col : undefined} strokeWidth={q.strokeWidth} strokeLinecap="round" strokeLinejoin="round" />)}
            </DG>))}
        </DG>
      </G>
    </DG>))}</G> : null;
  const hands = AS.length ? <Layer fs={fs} motion="still" K={K} u={u} w={w} h={h}>
    <Defs>
      {SHW ? SHW.regions.map((_: any, k: number) => <ClipPath key={k} id={id("shc" + k)}>{ST.shadow[k]}</ClipPath>) : null}
      <ClipPath id={id("sh")}><G transform={ZOOM_T}>{ST.layers[iCollar]}</G></ClipPath>
      {AS.map(([art, i]) => (
        <React.Fragment key={art}>
          <DLG {...p} id={id("sg" + i)} gradientUnits="userSpaceOnUse" sel={(f: any) => { "worklet"; const h = pick(f, art), s = h ? h.shadow : null; return s && s.on ? { x1: s.x1, y1: s.y1, x2: s.x2, y2: s.y2 } : { x1: 0, y1: 0, x2: 1, y2: 0 }; }}>{stops([[0, 0.26], [0.45, 0.1], [1, 0]])}</DLG>
          <DLG {...p} id={id("mg" + i)} gradientUnits="userSpaceOnUse" sel={(f: any) => { "worklet"; const h = pick(f, art), s = h ? h.seam : null; return s && s.on ? { x1: s.x1, y1: s.y1, x2: s.x2, y2: s.y2 } : { x1: 0, y1: 0, x2: 1, y2: 0 }; }}>{stops([[0, 0], [0.14, 0.85], [0.5, 0.85], [1, 0]])}</DLG>
        </React.Fragment>))}
    </Defs>
    <G transform={STAGE_T}><DG {...p} sel={lift}>
      {armShadow}
      {AS.map(([art]) => (
        <DG key={art} {...p} sel={(f: any) => { "worklet"; const h = pick(f, art); return { matrix: h ? h.matrix : AWAY, opacity: h ? 1 : 0 }; }}>
          {ART[art].paths.map((q: any, k: number) => <Path key={k} d={q.d} fill={q.fill ? COL[q.fill] : "none"} fillRule={q.evenOdd ? "evenodd" : "nonzero"} stroke={q.stroke ? COL[q.stroke] : undefined} strokeWidth={q.strokeWidth} strokeLinecap="round" strokeLinejoin="round" />)}
        </DG>))}
      {AS.map(([art, i]) => (
        <React.Fragment key={art}>
          <G clipPath={url("sh")}><DP {...p} fill={url("sg" + i)} sel={(f: any) => { "worklet"; const h = pick(f, art); return { d: h && h.shadow.on ? h.shadow.d : NONE }; }} /></G>
          <DP {...p} fill={COL.sleeve} sel={(f: any) => { "worklet"; const h = pick(f, art); return { d: h && h.sleeve ? h.sleeve : NONE }; }} />
          <DP {...p} fill="none" stroke={COL.cuff} strokeWidth={5} strokeLinecap="round" opacity={COL.cuffOpacity} sel={(f: any) => { "worklet"; const h = pick(f, art); return { d: h && h.cuff ? h.cuff : NONE }; }} />
        </React.Fragment>))}
      {AS.map(([art, i]) => <DP key={art} {...p} fill="none" stroke={url("mg" + i)} strokeWidth={3} strokeLinecap="round" sel={(f: any) => { "worklet"; const h = pick(f, art); return { d: h && h.seam.on ? h.seam.d : NONE }; }} />)}
    </DG></G>
  </Layer> : null;

  return (
    <>
      {blob ? <Layer fs={fs} motion="still" K={K} u={u} w={w} h={h}><Path d={L.blob.d} fill={blobColour ?? L.blob.colour} /></Layer> : null}
      {layers}
      {noHands ? null : hands}
      {/* the matte, painted once, in the colour behind Pip: below the blob's cut line, everything outside the blob is covered,
          so the body and the hands end exactly on the blob's curve (a moving layer cannot carry a fixed cut) */}
      {noCut ? null : <Layer fs={fs} motion="still" K={K} u={u} w={w} h={h}><Path d={`M-400 -400H800V800H-400Z ${L.cut}`} fillRule="evenodd" fill={backdrop} /></Layer>}
    </>);
});

/** Pip, drawn live. Decorative: the screen around him says what happened. */
export const Pip = forwardRef<PipHandle, PipProps>(function Pip({ variant = "pip", size, blob = true, blobColour, backdrop, face = "calm", hold = null, labNoCut = false, labNoHands = false }, ref) {
  const B = useMemo(() => bundle(variant), [variant]);
  const uid = useMemo(() => "p" + UID++ + "_", []);
  const reduced = useReducedMotion();
  const ui = useMemo(() => ({ I: B.I, FK: B.FK, PREP: B.PREP, hairEvery: HAIR_EVERY[variant] }), [B, variant]);
  const bun = useSharedValue<any>(ui);
  const fc = useSharedValue<any>(faceStill(B.FK, face));
  const fs = useSharedValue<any>(solveIdle(B.I, 0, faceNow(B.FK, faceStill(B.FK, face), 0)));
  const hs = useSharedValue<any>(null), hver = useSharedValue(-1), hf = useSharedValue(0);
  const t0 = useSharedValue(-1), mom = useSharedValue<string>(""), pend = useSharedValue<string>(""), startAt = useSharedValue(0), nowT = useSharedValue(0), still = useSharedValue(reduced ? 1 : 0);
  const holdM = useSharedValue<string>(hold ? hold[0] : ""), holdT = useSharedValue(hold ? hold[1] : 0);
  const done = useRef<(() => void) | null>(null);
  const [playing, setPlaying] = useState<PipMove | null>(null);
  const artsOf = useCallback((m: PipMove | null) => (m ? B.PREP[m].hands.map((h: any) => h.art as string) : []), [B]);
  const arts = useMemo(() => artsOf(hold ? hold[0] : playing), [artsOf, hold, playing]);
  const onDone = useCallback(() => { setPlaying(null); const d = done.current; done.current = null; if (d) d(); }, []);
  // whole-body motion: the outer view moves (native transform: nothing repaints), pivoting at Pip's feet
  const by = useSharedValue(0), bsc = useSharedValue(1), brot = useSharedValue(0);
  const bodyStyle = useAnimatedStyle(() => ({ transform: [{ translateY: by.value }, { rotate: brot.value + "deg" }, { scale: bsc.value }] }));

  useEffect(() => { bun.value = ui; fc.value = faceStill(B.FK, face); hs.value = null; hver.value = -1; }, [ui]);   // eslint-disable-line react-hooks/exhaustive-deps
  useEffect(() => { still.value = reduced ? 1 : 0; }, [reduced, still]);
  useEffect(() => { holdM.value = hold ? hold[0] : ""; holdT.value = hold ? hold[1] : 0; }, [hold, holdM, holdT]);

  useFrameCallback(info => {
    const Bn = bun.value, ts = info.timestamp; nowT.value = ts;
    let f: any;
    if (pend.value !== "" && ts >= startAt.value) { mom.value = pend.value; pend.value = ""; t0.value = ts; }   // a move starts once the face is calm
    if (holdM.value !== "") { f = overlayIdle(Bn.I, solveFrame(Bn.PREP[holdM.value], holdT.value), 0); }
    else if (still.value === 1) { f = solveIdle(Bn.I, 0, faceNow(Bn.FK, fc.value, ts)); }               // reduced motion: no idle, no moves; the face still changes
    else if (t0.value < 0) { f = solveIdle(Bn.I, info.timeSinceFirstFrame, faceNow(Bn.FK, fc.value, ts)); }
    else { const P = Bn.PREP[mom.value], t = ts - t0.value;
      f = overlayIdle(Bn.I, solveFrame(P, t), info.timeSinceFirstFrame);
      if (t >= P.totalMs) { t0.value = -1; fc.value = { from: Bn.FK.rest.calm.v, to: "calm", t0: -1e9 }; runOnJS(onDone)(); } }   // = faceStill(FK, "calm"), which is not a worklet
    fs.value = f;
    if (f.hair && f.hair.ver !== hver.value && (hf.value = hf.value + 1) % Bn.hairEvery === 0) { hver.value = f.hair.ver; hs.value = f.hair; }
  });

  useImperativeHandle(ref, () => ({
    play: (move: PipMove) => new Promise<void>(res => {
      if (reduced) { res(); return; }
      const prev = done.current; done.current = () => { if (prev) prev(); res(); };
      setPlaying(move);   // mount this move's hands first; the move starts on the UI thread once the face is calm
      runOnUI(() => { "worklet"; const calm = fc.value.to === "calm" && nowT.value - fc.value.t0 >= FACE_MS;
        if (!calm) fc.value = faceGo(bun.value.FK, fc.value, "calm", nowT.value);
        pend.value = move; startAt.value = calm ? 0 : nowT.value + FACE_MS; })();
    }),
    face: (name: PipFace) => { runOnUI(() => { "worklet"; fc.value = faceGo(bun.value.FK, fc.value, name, nowT.value); })(); },
    body: (kind: PipBody) => new Promise<void>(res => {
      if (reduced) { res(); return; }
      const end = (fin?: boolean) => { "worklet"; if (fin !== undefined) runOnJS(res)(); };
      const up = Easing.out(Easing.quad), down = Easing.in(Easing.quad);
      if (kind === "hop") {            // up 6% of the height and down, a small squash on landing
        by.value = withSequence(withTiming(-0.06 * size, { duration: 180, easing: up }), withTiming(0, { duration: 170, easing: down }));
        bsc.value = withSequence(withTiming(1, { duration: 350 }), withTiming(0.97, { duration: 60 }), withSpring(1, { damping: 9, stiffness: 260 }, end));
      } else if (kind === "pop") {     // grow 8% fast, settle with a small bounce
        bsc.value = withSequence(withTiming(1.08, { duration: 140, easing: up }), withSpring(1, { damping: 7, stiffness: 220 }, end));
      } else {                         // tilt left, right, settle
        brot.value = withSequence(withTiming(-4, { duration: 140, easing: up }), withTiming(4, { duration: 260 }), withTiming(-1.5, { duration: 180 }), withTiming(0, { duration: 140, easing: down }, end));
      }
    }),
  }), [reduced, pend, startAt, fc, bun, nowT, by, bsc, brot, size]);

  const h = Math.round(size * VIEW.h / VIEW.w);
  return (
    <Animated.View style={[{ width: size, height: h, transformOrigin: "50% 100%" }, bodyStyle]} accessible={false} importantForAccessibility="no-hide-descendants" pointerEvents="none">
      {/* one fixed box for all layers: a layer that breathes or lifts never shows its edge past Pip's picture */}
      <View style={{ width: size, height: h, overflow: "hidden" }}>
        <Figure fs={fs} hs={hs} B={B} uid={uid} w={size} h={h} blob={blob} blobColour={blobColour} backdrop={backdrop} noCut={labNoCut} noHands={labNoHands} arts={arts} />
      </View>
    </Animated.View>);
});
